"""Download endpoints for CSV/XLSX exports generated by the background worker."""
from __future__ import annotations

import os
from datetime import datetime, timezone

from fastapi import APIRouter, Depends, HTTPException, Query
from fastapi.responses import FileResponse

from app.auth import CurrentUser, get_current_user
from app.settings import settings

router = APIRouter(prefix="/exports", tags=["exports"])

EXPORT_ROOT = settings.export_root
MEDIA_TYPES = {
    ".csv": "text/csv",
    ".xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
}


@router.get("")
def list_exports(user: CurrentUser = Depends(get_current_user)):
    """List finished exports for the caller."""
    user_dir = os.path.join(EXPORT_ROOT, str(user.id))
    if not os.path.isdir(user_dir):
        return []
    entries = []
    for name in sorted(os.listdir(user_dir)):
        stat = os.stat(os.path.join(user_dir, name))
        entries.append(
            {
                "name": name,
                "size": stat.st_size,
                "created_at": datetime.fromtimestamp(stat.st_mtime, tz=timezone.utc),
            }
        )
    return entries


@router.get("/download")
def download_export(
    name: str = Query(..., min_length=1),
    user: CurrentUser = Depends(get_current_user),
):
    """Stream one of the caller's finished exports."""
    export_path = os.path.join(EXPORT_ROOT, str(user.id), name)
    if not os.path.isfile(export_path):
        raise HTTPException(status_code=404, detail="Export not found")
    extension = os.path.splitext(name)[1].lower()
    return FileResponse(
        export_path,
        media_type=MEDIA_TYPES.get(extension, "application/octet-stream"),
        filename=os.path.basename(export_path),
    )
